mapper.select:
SELECT payment.id AS payment_id, payment.order_id, payment.toss_order_id AS gateway_order_id, payment.amount, payment.method, payment.status, cancellation.status AS cancellation_status, cancellation.request_type AS cancellation_request_type, payment.requested_at, payment.approved_at, payment.canceled_at, payment.expiration_checked_at FROM payments AS payment LEFT JOIN payment_cancellations AS cancellation ON cancellation.id = ( SELECT MAX(recent_cancellation.id) FROM payment_cancellations AS recent_cancellation WHERE recent_cancellation.payment_id = payment.id AND NOT ( recent_cancellation.request_type = 'SYSTEM_COMPENSATION' AND recent_cancellation.status = 'FAILED' AND recent_cancellation.failure_code = 'PAYMENT_COMPLETED' ) )
WHERE payment.status = #{status}
ORDER BY payment.created_at DESC, payment.id DESC

mapper.update:
UPDATE payments
SET provider = #{provider}
WHERE id = #{paymentId}
  AND status = 'READY'
  AND payment_key IS NULL

UPDATE payments
SET status = 'CANCELED',
    canceled_at = #{canceledAt}
WHERE id = #{paymentId}
  AND status = 'DONE'

UPDATE payments
SET payment_key = #{paymentKey}
WHERE id = #{paymentId}
  AND status IN ('READY', 'DONE', 'EXPIRED')
  AND (payment_key IS NULL OR payment_key = #{paymentKey})

UPDATE payments
SET payment_key = NULL
WHERE id = #{paymentId}
  AND status = 'READY'
  AND payment_key = #{paymentKey}

UPDATE payments
SET idempotency_key = #{idempotencyKey}
WHERE id = #{paymentId}
  AND status = 'READY'
  AND payment_key = #{paymentKey}

UPDATE payment_cancellations
SET status = 'FAILED',
    failure_code = #{failureCode}
WHERE id = #{cancellationId}
  AND status = 'REQUESTED'

UPDATE payments
SET failure_code = 'GATEWAY_VOIDED_KEPT'
WHERE id = #{paymentId}
  AND status = 'DONE'
  AND payment_key = #{paymentKey}
  AND failure_code IS NULL

UPDATE payments
SET gateway_held_at = #{heldAt}
WHERE id = #{paymentId}
  AND status = 'DONE'
  AND payment_key = #{paymentKey}
  AND gateway_held_at IS NULL

UPDATE payments
SET gateway_captured_at = #{capturedAt}
WHERE id = #{paymentId}
  AND status = 'DONE'
  AND payment_key = #{paymentKey}
  AND gateway_held_at IS NOT NULL
  AND gateway_captured_at IS NULL
